func appendListTriggeringInstructions(dst []byte, s []ListTriggeringInstructions) []byte {
	var d SmallGroupSize8Encoding
	d.BlockLength = 3
	d.NumInGroup = uint8(len(s))
	dst, b := extend(dst, SmallGroupSize8EncodingSize)
	d.putTo(b)
	for i := range s {
		dst, b = extend(dst, 3)
		s[i].putBlock(b)
		dst = s[i].appendRest(dst)
	}
	return dst
}
